import java.util.Scanner;

public class Main {
    static final int N = 505;
    static int n, m, P, maxn;
    static long[] fac = new long[N];
    static long[] inv = new long[N];
    static long[][] F = new long[N][N];
    static long[][] G = new long[N][N];
    static long[] f = new long[N];
    static long[] g = new long[N];

    static long fast_pow(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % P;
            base = (base * base) % P;
            exp >>= 1;
        }
        return result;
    }

    static long comb(int x, int y) {
        if (x < y || y < 0) return 0;
        return fac[x] * inv[y] % P * inv[x - y] % P;
    }

    static int sum_series(int x) {
        return x * (x + 1) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();
        maxn = n + 1;

        fac[0] = 1;
        inv[0] = 1;
        for (int i = 1; i <= maxn; i++) {
            fac[i] = (fac[i - 1] * i) % P;
        }
        for (int i = 1; i <= maxn; i++) {
            inv[i] = fast_pow(fac[i], P - 2);
        }

        f[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                f[i] = (f[i] + f[j] * f[i - 1 - j] % P * comb(i - 1, j)) % P;
                g[i] = (g[i] + (((g[j] * f[i - 1 - j]) % P + (f[j] * g[i - 1 - j]) % P) * (i + 1) % P
                        + f[j] * f[i - 1 - j] % P * (sum_series(j) + sum_series(i - 1 - j)) % P) * comb(i - 1, j)) % P;
            }
            f[i] = (f[i] * (i + 1)) % P;
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                F[i][j] = 0;
                G[i][j] = 0;
            }
        }
        F[0][0] = 1;
        for (int j = 0; j <= n; j++) {
            F[0][j] = 1;
        }
        for (int i = 1; i <= m; i++) {
            F[i][i] = f[i];
            G[i][i] = g[i];
            for (int j = i + 1; j <= n; j++) {
                F[i][j] = F[i][j - 1];
                G[i][j] = G[i][j - 1];
                for (int l = 1; l <= i; l++) {
                    F[i][j] = (F[i][j] + F[i - l][j - 1 - l] * f[l] % P * comb(i, l)) % P;
                    G[i][j] = (G[i][j] + (G[i - l][j - 1 - l] * f[l] % P + F[i - l][j - 1 - l] * g[l] % P) * comb(i, l)) % P;
                }
            }
        }
        System.out.println(G[m][n]);
        sc.close();
    }
}
